/*:
 * @target MZ
 * @plugindesc Create event effects in realtime without drawing
 * @author Sang Hendrix
 * @url https://sanghendrix.itch.io
 *
 * @help
 * Verion 1.0.7
 * For support or bug report, please contact via Discord
 * Discord: https://discord.gg/YKPscqHV8b
 * Patreon: https://www.patreon.com/SangHendrix
 * ----------------------------------------------------------------------------
 * This RPG Maker MZ plugin lets you create event effects and preview them in
 * real time extremely easily. Make trees sway in the wind, balls bounce,
 * crops jump as they wait to be harvested, magic books float, and so much more.
 * Unleash your creativity!
 * ----------------------------------------------------------------------------
 * HOW TO USE
 * ----------------------------------------------------------------------------
 * Move your mouse to bottom-right corner and hover on the dog icon,
 * then select 🕺 Event Effects.
 * 
 * APPLY METHODS (3 ways to apply effects)
 * 1. Click on button "✅ This" (for current event) or "✅ All" (for all event with same name)
 * 2. Add comment <event effect: preset name> to an event's page
 * 3. Call plugin command Play Event Effect
 * ----------------------------------------------------------------------------
 * TERMS OF USE
 * ----------------------------------------------------------------------------
 * https://www.rpgmakeractioncombat.com/p/sang-hendrixs-rpg-maker-plugin-terms-of.html
 * ----------------------------------------------------------------------------
 * 
 * @param showBuilderButton
 * @text Show Builder Button
 * @desc Show the editor button in bottom right corner. Will be disabled automatically when game deployed.
 * @type boolean
 * @default true
 * 
 * @command PlayEventEffect
 * @text Play Event Effect
 * @desc Play an event effect animation from a preset
 *
 * @arg presetName
 * @text Play from Preset
 * @type string
 * @desc Name of the preset to play (write "none" to reset/remove effect)
 *
 * @arg target
 * @text Target
 * @type string
 * @default this
 * @desc Support: this, player, event id, event name, actor [actor id]
 *
 * @arg playAmount
 * @text Play Amount
 * @type string
 * @default once
 * @desc Number of times to play: once, forever, or any number
 * 
 * @arg transition
 * @text Transition
 * @type string
 * @default 0
 * @desc Number of frames to transition in/swap effects. 0 = instant.
 * 
 * @arg permanent
 * @text Permanent
 * @desc Save effect permanently (persists across maps). Use this with caution.
 * @type boolean
 * @default false
 * 
 * @command StopEventEffect
 * @text Stop Event Effect
 * @desc Stop and remove event effect animation from target
 *
 * @arg target
 * @text Target
 * @type string
 * @default this
 * @desc Support: this, player, event id, event name, actor [actor id]
 * 
 * @arg transition
 * @text Transition
 * @type string
 * @default 0
 * @desc Number of frames to transition out the effect. 0 = instant.
 * 
 * @arg permanent
 * @text Permanent
 * @desc Also remove the permanently saved effect for this target.
 * @type boolean
 * @default false
 */

var Imported = Imported || {};
Imported.Hendrix_Realtime_Event_Effects = true;

